- SOURCE_CLAIM_JSON: {"title":"Ethiopia annual inflation slows slightly to 33.5% in July","publisher":"Ethiopian Tribune / Reuters","publication_date":"2022-08-05","url":"https://ethiopiantribune.com/2022/08/ethiopia-annual-inflation-slows-slightly-to-33-5-in-july/","claim":"Reuters reported that Ethiopia’s inflation eased only slightly to 33.5% year on year in July 2022, with food inflation still at 35.5% and non-food inflation at 30.4%.","locator":"lines 30-37","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"Reuters dateline and figures reproduced by a republisher; good for the specific inflation reading, though not as strong as the original Reuters page.","final_evidence_use":"final_evidence","period_fit":"Directly within 2022.","ruler_attribution":"This is an outcome under Abiy’s government, not proof of personal choice; it reflects the macroeconomic environment his administration had to manage.","contrary_evidence":["Inflation slowing slightly is a small positive, but levels remained extremely high.","The article does not attribute the inflation path to one policy choice."],"lenses":["5B.3","5B.9","5B.10"]}
